// Extract comment data from Meta webhook payload
const entries = $input.first().json.body.entry || [];
const comments = [];

for (const entry of entries) {
  const changes = entry.changes || [];
  for (const change of changes) {
    if (change.field === 'comments') {
      const value = change.value;
      comments.push({
        commentId: value.id,
        commentText: value.text,
        commenterId: value.from?.id,
        commenterName: value.from?.username || 'Unknown',
        mediaId: value.media?.id,
        timestamp: value.created_time
      });
    }
  }
}

return comments.map(c => ({ json: c }));

